import{c as t,Q as a,j as o,m as i}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Categorization","description":"","frontmatter":{},"headers":[],"relativePath":"automation/categorization.md","filePath":"automation/categorization.md","lastUpdated":null}'),r={name:"automation/categorization.md"};function n(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="categorization" tabindex="-1">Categorization <a class="header-anchor" href="#categorization" aria-label="Permalink to &quot;Categorization&quot;">​</a></h1><p>How FinSight decides what category a transaction belongs to.</p><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline&quot;">​</a></h2><p><code>finsight-core::categorize</code> runs a strict priority:</p><ol><li><strong>Rules</strong> — pattern rules first; if one matches, category is set, no LLM call.</li><li><strong>LLM</strong> — only for the uncategorized remainder, if a provider is configured and <strong>Agent categorization</strong> is enabled. Sends the redacted merchant description and amount — not the whole ledger — via <code>finsight-agent::categorizer</code>.</li><li><strong>Centroid fallback</strong> — semantic similarity to category centroids (<code>repos/category_centroids</code>) learned from your past categorizations.</li><li><strong>Heuristics</strong> — keyword and amount heuristics when nothing above fits.</li><li><strong>Uncategorized</strong> — left for you in the review queue.</li></ol><p>This means a rule always beats the model, and the model only sees what no rule covers.</p><h2 id="confidence-review" tabindex="-1">Confidence &amp; review <a class="header-anchor" href="#confidence-review" aria-label="Permalink to &quot;Confidence &amp; review&quot;">​</a></h2><p>Each LLM suggestion carries a confidence score (0–1, clamped). Low-confidence rows land in <strong>Insights → Needs Review</strong> and <strong>Transactions → Review</strong> instead of being auto-applied. Fixing them trains the centroid for next time.</p><h2 id="local-vs-remote" tabindex="-1">Local vs remote <a class="header-anchor" href="#local-vs-remote" aria-label="Permalink to &quot;Local vs remote&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Data leaves server?</th></tr></thead><tbody><tr><td>Ollama (local)</td><td>No — same payload over your LAN</td></tr><tr><td>Cloud provider</td><td>Yes — merchant + amount of uncategorized rows only</td></tr></tbody></table><p>The provider key is per-user inside <code>data.sqlcipher</code>. Disabling Agent categorization stops all LLM calls immediately.</p><h2 id="tuning" tabindex="-1">Tuning <a class="header-anchor" href="#tuning" aria-label="Permalink to &quot;Tuning&quot;">​</a></h2><ul><li>Create a <strong>rule</strong> for any merchant that is consistently mis-categorized — that merchant will never hit the LLM again.</li><li>Correct a low-confidence row manually; the centroid learns the correction.</li><li>Review <strong>Rules → Proposals</strong> to promote a repeated correction into a rule.</li></ul><p>See also: <a href="/FinSight/automation/rules">Rules</a>, <a href="/FinSight/configuration/ollama">Provider config</a>.</p>',14)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
